extension PracticeWorkshop {
    static let fhsa: [Self] = [
        .init("fhsa-cash-gap", "Estimate your cash at closing", "Nora has a target cash amount for a qualifying home purchase. A withdrawal quote tells her what the account could provide.", "A qualifying withdrawal can help fund a first home. Compare the withdrawal with cash needed and verify eligibility before relying on it.", ("Cash needed (CAD)", 18000), .subtract, ("Expected qualifying withdrawal (CAD)", 12500), "Cash still needed", ("What is the gap if the withdrawal is $14,200?", 14200), "Having an FHSA balance automatically makes every withdrawal qualifying.", false, "What should Nora verify?", "Check CRA conditions and coordinate with the issuer before withdrawing.", "Count the full balance as qualifying without checking.", "Eligibility and payment timing matter separately from how much is saved."),
        .init("fhsa-room-log", "Track room across accounts", "Eli has two FHSAs. Both institutions recorded a deposit.", "Track contributions and direct RRSP transfers together when checking available FHSA participation room across accounts.", ("Deposits at Bank A (CAD)", 2400), .add, ("Deposits at Bank B (CAD)", 1600), "Room used", ("If Bank B has $1,850, how much room was used?", 1850), "Opening a second FHSA gives you a separate contribution allowance.", false, "How should Eli verify room?", "Use one record for all FHSAs and check the CRA’s information.", "Calculate each bank’s room independently.", "Participation room is shared across accounts."),
        .init("fhsa-deduction-record", "Reconcile the deduction records", "Reese’s issuer recorded both a cash contribution and a direct RRSP transfer. Assume the cash contribution is eligible.", "Direct RRSP transfers generally use FHSA room but are excluded from deductible cash contributions.", ("Combined deposits and transfers (CAD)", 3000), .subtract, ("Direct transfer included (CAD)", 800), "Potentially deductible cash contribution", ("If the transfer was $1,400, how much was contributed in cash?", 1400), "The combined total automatically equals the amount deductible.", false, "Which records separate cash from transfers?", "Use the issuer’s FHSA statement and transaction records.", "Use only the current market value of the holdings.", "The source of the deposit determines the treatment in this example."),
        .init("fhsa-home-gap", "Compare two closing scenarios", "Robin looks at how much other cash would be needed if the eligible withdrawal is smaller than expected.", "Separate the anticipated home cash requirement from the portion funded by an eligible withdrawal. This helps you plan if either amount changes.", ("Closing cash target (CAD)", 16000), .subtract, ("FHSA amount available (CAD)", 10000), "Other funds needed", ("If the available amount falls to $8,800, how much other cash is needed?", 8800), "A lower available FHSA amount increases the gap, all else equal.", true, "What should Robin prepare for?", "Confirm the amount available and plan for the remaining cash.", "Assume the quote from last month will always apply.", "The amount available can change with holding values and account timing."),
        .init("fhsa-ordinary-net", "Estimate an ordinary withdrawal", "A fictional issuer quotes withholding on an ordinary FHSA withdrawal. The quote is illustrative.", "An ordinary withdrawal is generally taxable. Subtract quoted withholding to estimate cash received; withholding and final tax can differ.", ("Gross withdrawal (CAD)", 1800), .subtract, ("Illustrative withholding (CAD)", 180), "Net cash received", ("If withholding is $270, what is the net amount?", 270), "The amount withheld always equals the final tax bill.", false, "What do you keep for tax records?", "The transaction statement with both gross withdrawal and withholding.", "A note of the net deposit only.", "The final calculation may require both gross proceeds and tax already paid."),
        .init("fhsa-institution-transfer", "Consolidate accounts with a direct transfer", "Taylor compares projected balances before asking two FHSA issuers to carry out an eligible direct transfer.", "A qualifying direct transfer between your FHSAs generally does not count as a new contribution. Let the institutions handle the transfer.", ("Receiving balance (CAD)", 2300), .add, ("Eligible direct transfer (CAD)", 1700), "Projected receiving balance before fees", ("If the direct transfer is $900, what is the new balance before fees?", 900), "A qualifying direct transfer between your FHSAs generally creates a new contribution.", false, "How should Taylor request the move?", "Have the receiving issuer help arrange the direct transfer.", "Withdraw personally and assume redepositing is equivalent.", "The transfer route matters for tax and room."),
        .init("fhsa-plan-no-home", "Plan an exit without a home purchase", "Dev decides against buying and compares what the RRSP balance might be after an eligible transfer.", "An eligible direct transfer to your RRSP or RRIF can generally defer tax. Verify eligibility and the steps with the issuers first.", ("Existing RRSP balance (CAD)", 4200), .add, ("Eligible direct transfer (CAD)", 2800), "Projected RRSP balance before fees", ("If the eligible transfer is $1,900, what is the projected balance?", 1900), "An eligible direct transfer can generally be made without immediate tax.", true, "Which action preserves the direct transfer route?", "Ask the institutions to handle it.", "Accept an ordinary withdrawal and assume the treatment is identical.", "Transfers and ordinary withdrawals are different transaction types.")
    ]

    static let credit: [Self] = [
        .init("credit-utilization", "Read the space left on a credit limit", "A balance appears beside a credit limit. Mo wants to know how much of the limit is unused before pending purchases.", "Available credit is the unused part of a limit. Utilization describes the portion in use. Pending transactions may change what is actually available.", ("Credit limit (CAD)", 2000), .subtract, ("Posted balance (CAD)", 650), "Unused limit before pending purchases", ("What is unused if the posted balance rises to $850?", 850), "Available credit is the same as cash you own.", false, "What should Mo consider before using it?", "Whether repayment fits and which pending transactions may post.", "Treat the entire available limit as money already earned.", "A limit describes borrowing capacity, while new borrowing creates an obligation."),
        .init("credit-pending", "Reconcile pending transactions", "An upcoming transaction is pending and its estimated amount is known.", "Pending charges may affect available credit before they become posted. Use the estimated amount to plan and verify the final amount later.", ("Already posted balance (CAD)", 430), .add, ("Expected pending purchase (CAD)", 80), "Estimated balance once posted", ("What is the projected balance if the purchase posts for $95?", 95), "Pending and posted amounts are always identical.", false, "What should you check later?", "Verify the final posted amount in your account.", "Assume the temporary authorization is always final.", "A pending authorization can differ from the settled charge."),
        .init("credit-interest", "Estimate the cost of carrying a balance", "A cardholder studies a simplified month with a constant balance and an illustrative monthly interest charge.", "When purchase interest applies, carrying a balance can cost more. Real credit card interest can depend on daily balances, dates, and terms.", ("Balance carried (CAD)", 750), .add, ("Illustrative interest (CAD)", 15), "Balance after interest only", ("What is the balance if the charge is $22?", 22), "The example models every card’s exact interest calculation.", false, "What should the cardholder check?", "The card agreement and charged interest on the statement.", "Assume the sample charge applies to every balance.", "The calculation here isolates one charge; actual terms control the amount."),
        .init("credit-pair", "Compare a partial payment with the balance", "Bria has reviewed the statement. Her planned payment exceeds the minimum but is below the full amount.", "Subtract the payment from the statement balance to check what remains before interest and new charges.", ("Statement balance (CAD)", 620), .subtract, ("Planned payment (CAD)", 200), "Unpaid statement amount", ("If Bria pays $410, what still remains?", 410), "A payment above the minimum always clears the statement.", false, "What follow-up helps Bria?", "Plan when the remaining amount will be paid and check interest terms.", "Treat the statement as settled after any payment.", "Partial payments reduce debt without necessarily avoiding interest."),
        .init("credit-refund", "Reconcile a posted refund", "One purchase is refunded after the statement closes. Jo checks what it did to the current balance.", "Subtract a posted refund to reconcile the current balance. Check the issuer’s rules and due amount before assuming a refund satisfies a required payment.", ("Current balance before refund (CAD)", 360), .subtract, ("Posted refund (CAD)", 65), "Current balance after refund", ("What is the balance if the refund is $115?", 115), "A posted refund always counts as the required minimum payment.", false, "Before the due date, what should Jo check?", "Verify the issuer’s shown amount due and scheduled payment.", "Assume the refund makes any due payment unnecessary.", "A credit to the account and a required payment can be treated differently."),
        .init("credit-loan-fee", "Add a fee to total borrowing cost", "An installment loan quote shows total scheduled payments and a separate opening fee.", "Count charges paid separately as well as scheduled payments. Compare total repayment, timing, and affordability across quotes.", ("Total scheduled payments (CAD)", 1320), .add, ("Fee paid separately (CAD)", 45), "Total cash paid", ("If the fee is $90, what is the total cash paid?", 90), "A fee outside scheduled payments still affects total cost.", true, "What should you confirm before adding a fee?", "Check that it isn’t already included in scheduled payments.", "Add any listed fee twice to be safe.", "Counting each cash outflow once makes offers comparable."),
        .init("credit-loan-term", "Compare the value of an extra payment", "An example lender shows the principal reduction from a payment after charges. There are no penalties in this exercise.", "An extra payment applied to principal reduces the remaining amount borrowed. Check whether fees, limits, or other terms affect extra payments.", ("Principal before payment (CAD)", 2100), .subtract, ("Extra principal payment (CAD)", 300), "Remaining principal", ("If the amount applied to principal is $450, what remains?", 450), "Every loan always permits unlimited extra payments on the same terms.", false, "What should the borrower confirm?", "How the lender applies extra payments and whether restrictions apply.", "Assume all payments are applied to principal only.", "The contract determines where the payment goes.")
    ]
}

extension PracticeWorkshop {
    static let planning: [Self] = [
        .init("plan-contribution-compare", "Compare two savings schedules", "A learner compares the cash contributed over a period before considering growth.", "Multiply the recurring contribution by the number of contributions. Actual ending value may differ because of returns, fees or withdrawals.", ("Monthly contribution (CAD)", 120), .multiply, ("Months of deposits", 12), "Cash contributed", ("What is contributed over 15 months at the same rate?", 15), "The sum of contributions always equals the final investment value.", false, "How should schedules be compared?", "Separate contributions from any assumed investment growth.", "Attribute every difference in accounts to market growth.", "The amount added and the return it earns are separate drivers."),
        .init("plan-start-later", "Measure the cost of a delayed start", "A target date still lies 24 months away. A six-month delay would leave 18 planned contributions.", "With a fixed contribution amount, fewer planned deposits means less cash contributed before considering growth. Rework the amount or date if the plan changes.", ("Monthly contribution (CAD)", 140), .multiply, ("Remaining deposits after delay", 18), "Contributions before target date", ("What would 24 deposits at the same amount total?", 24), "Delaying contributions while keeping the target date can reduce the number of deposits.", true, "What should the saver adjust after the delay?", "Revisit the contribution, target date, or target amount.", "Keep all assumptions and expect unchanged results.", "The revised plan needs to reflect how many contributions remain."),
        .init("plan-inflation", "Update spending for higher prices", "A scenario estimates current annual spending and a possible annual increase in future costs.", "Add projected cost changes to the current spending estimate. Try more than one inflation scenario.", ("Current annual spending (CAD)", 28000), .add, ("Estimated annual cost increase (CAD)", 1400), "Projected annual spending", ("If spending rises by $2,100 instead, what is the projection?", 2100), "A future spending estimate can use more than one price scenario.", true, "What should you do with the higher estimate?", "Test whether the plan still works at that level.", "Discard it because the current spending number is known.", "Plans are stronger when they account for uncertain costs."),
        .init("plan-pension-delay", "Test a delayed pension start", "A simplified plan has a fixed annual shortfall until a fictional pension begins.", "The bridge amount equals the annual shortfall times the years it lasts when amounts are held constant. Timing changes that total.", ("Annual shortfall (CAD)", 9000), .multiply, ("Years before pension", 4), "Total bridge amount", ("If the pension starts in six years, what is the bridge amount?", 6), "Adding a bridge year adds another year of shortfall in this model.", true, "What should you verify before using the result?", "Confirm the income start date and test alternative dates.", "Assume the pension starts on whichever date you retire.", "Different income sources can start at different times."),
        .init("plan-part-time", "Compare a phased retirement year", "A fictional plan includes income from part-time work and a separate gap that needs funding.", "Subtract expected net part-time income from the amount that needs funding. Try a reduced-hours scenario too.", ("Income gap before part-time work (CAD)", 16200), .subtract, ("Expected net part-time income (CAD)", 6000), "Gap after part-time income", ("What if part-time income is only $3,500?", 3500), "Part-time income always stays fixed through retirement.", false, "What should the plan test?", "A case with fewer hours or no part-time income.", "Assume the original estimate stays the same indefinitely.", "Testing a smaller income source shows how much it matters.")
    ]
}
